import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const EnhancedEmployeeDashboard = () => {
  const [profile, setProfile] = useState(null);
  const [stats, setStats] = useState({
    totalBills: 0,
    pendingBills: 0,
    approvedBills: 0,
    totalAmount: 0,
    activeTrips: 0,
    completedTrips: 0
  });
  const [recentBills, setRecentBills] = useState([]);
  const [recentTrips, setRecentTrips] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const navigate = useNavigate();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      // Fetch profile
      const profileResponse = await axios.get('http://localhost:8000/profile', { headers });
      setProfile(profileResponse.data);

      // Fetch bills (mock data for now)
      // In real implementation, you'd have endpoints for these
      setStats({
        totalBills: 12,
        pendingBills: 3,
        approvedBills: 8,
        totalAmount: 45670,
        activeTrips: 1,
        completedTrips: 5
      });

      setRecentBills([
        { id: 1, description: 'Client Dinner', amount: 2500, status: 'approved', date: '2024-01-15' },
        { id: 2, description: 'Travel Expenses', amount: 8900, status: 'pending', date: '2024-01-14' },
        { id: 3, description: 'Office Supplies', amount: 1200, status: 'approved', date: '2024-01-12' }
      ]);

      setRecentTrips([
        { id: 1, destination: 'Mumbai', purpose: 'Client Meeting', status: 'active', startDate: '2024-01-20' },
        { id: 2, destination: 'Delhi', purpose: 'Conference', status: 'completed', startDate: '2024-01-10' }
      ]);

    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      if (error.response?.status === 401) {
        localStorage.removeItem('token');
        navigate('/login');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      pending: { class: 'badge-warning', icon: '⏳', text: 'Pending' },
      approved: { class: 'badge-success', icon: '✅', text: 'Approved' },
      rejected: { class: 'badge-error', icon: '❌', text: 'Rejected' },
      active: { class: 'badge-primary', icon: '🚀', text: 'Active' },
      completed: { class: 'badge-secondary', icon: '✓', text: 'Completed' }
    };
    
    const config = statusConfig[status] || statusConfig.pending;
    return (
      <span className={`badge ${config.class}`}>
        {config.icon} {config.text}
      </span>
    );
  };

  if (loading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>Loading your dashboard...</p>
      </div>
    );
  }

  return (
    <div className="employee-dashboard">
      {/* Header */}
      <div className="dashboard-header">
        <div className="header-content">
          <div className="header-info">
            <div className="user-avatar">
              {profile?.full_name?.charAt(0) || profile?.username?.charAt(0) || 'U'}
            </div>
            <div className="user-details">
              <h1 className="user-name">
                Welcome back, {profile?.full_name || profile?.username}!
              </h1>
              <p className="user-role">
                {profile?.designation?.replace('_', ' ').toUpperCase()} • {profile?.department}
              </p>
            </div>
          </div>
          <div className="header-actions">
            <button className="btn btn-outline btn-sm" onClick={() => navigate('/profile')}>
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M20 21V19C20 17.9391 19.5786 16.9217 18.8284 16.1716C18.0783 15.4214 17.0609 15 16 15H8C6.93913 15 5.92172 15.4214 5.17157 16.1716C4.42143 16.9217 4 17.9391 4 19V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <circle cx="12" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
              Profile
            </button>
            <button className="btn btn-error btn-sm" onClick={handleLogout}>
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M9 21H5C4.46957 21 3.96086 20.7893 3.58579 20.4142C3.21071 20.0391 3 19.5304 3 19V5C3 4.46957 3.21071 3.96086 3.58579 3.58579C3.96086 3.21071 4.46957 3 5 3H9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <polyline points="16,17 21,12 16,7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                <line x1="21" y1="12" x2="9" y2="12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
              Logout
            </button>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="stats-section">
        <div className="stats-grid">
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--primary-100)', color: 'var(--primary-600)' }}>
              📄
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Total Bills</h3>
              <p className="stats-card-value">{stats.totalBills}</p>
            </div>
          </div>
          
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--warning-100)', color: 'var(--warning-600)' }}>
              ⏳
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Pending Approval</h3>
              <p className="stats-card-value">{stats.pendingBills}</p>
            </div>
          </div>
          
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--success-100)', color: 'var(--success-600)' }}>
              💰
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Total Amount</h3>
              <p className="stats-card-value">{formatCurrency(stats.totalAmount)}</p>
            </div>
          </div>
          
          <div className="stats-card">
            <div className="stats-card-icon" style={{ backgroundColor: 'var(--secondary-100)', color: 'var(--secondary-600)' }}>
              ✈️
            </div>
            <div className="stats-card-content">
              <h3 className="stats-card-title">Active Trips</h3>
              <p className="stats-card-value">{stats.activeTrips}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="nav-tabs">
        <button
          className={`nav-tab ${activeTab === 'overview' ? 'active' : ''}`}
          onClick={() => setActiveTab('overview')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect x="3" y="3" width="18" height="18" rx="2" ry="2" stroke="currentColor" strokeWidth="2"/>
            <line x1="9" y1="9" x2="15" y2="9" stroke="currentColor" strokeWidth="2"/>
            <line x1="9" y1="15" x2="15" y2="15" stroke="currentColor" strokeWidth="2"/>
          </svg>
          Overview
        </button>
        <button
          className={`nav-tab ${activeTab === 'bills' ? 'active' : ''}`}
          onClick={() => setActiveTab('bills')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M14 2H6C5.46957 2 4.96086 2.21071 4.58579 2.58579C4.21071 2.96086 4 3.46957 4 4V20C4 20.5304 4.21071 21.0391 4.58579 21.4142C4.96086 21.7893 5.46957 22 6 22H18C18.5304 22 19.0391 21.7893 19.4142 21.4142C19.7893 21.0391 20 20.5304 20 20V8L14 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <polyline points="14,2 14,8 20,8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          Recent Bills
        </button>
        <button
          className={`nav-tab ${activeTab === 'trips' ? 'active' : ''}`}
          onClick={() => setActiveTab('trips')}
        >
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M21 16V8C21 6.89543 20.1046 6 19 6H5C3.89543 6 3 6.89543 3 8V16C3 17.1046 3.89543 18 5 18H19C20.1046 18 21 17.1046 21 16Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            <polyline points="7,10 12,15 17,10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          Trips
        </button>
      </div>

      {/* Tab Content */}
      <div className="tab-content">
        {activeTab === 'overview' && (
          <div className="overview-section">
            <div className="quick-actions">
              <h2 className="section-title">Quick Actions</h2>
              <div className="action-cards">
                <div className="action-card" onClick={() => navigate('/upload')}>
                  <div className="action-icon">
                    <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M21 15V19C21 19.5304 20.7893 20.0391 20.4142 20.4142C20.0391 20.7893 19.5304 21 19 21H5C4.46957 21 3.96086 20.7893 3.58579 20.4142C3.21071 20.0391 3 19.5304 3 19V15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <polyline points="17,8 12,3 7,8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <line x1="12" y1="3" x2="12" y2="15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </div>
                  <h3>Upload Bill</h3>
                  <p>Submit a new expense bill for approval</p>
                </div>
                
                <div className="action-card" onClick={() => navigate('/budget')}>
                  <div className="action-icon">
                    <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M21 16V8C21 6.89543 20.1046 6 19 6H5C3.89543 6 3 6.89543 3 8V16C3 17.1046 3.89543 18 5 18H19C20.1046 18 21 17.1046 21 16Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <line x1="3" y1="10" x2="21" y2="10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </div>
                  <h3>Trip Budget</h3>
                  <p>Plan and manage your business trips</p>
                </div>
                
                <div className="action-card" onClick={() => navigate('/profile')}>
                  <div className="action-icon">
                    <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M20 21V19C20 17.9391 19.5786 16.9217 18.8284 16.1716C18.0783 15.4214 17.0609 15 16 15H8C6.93913 15 5.92172 15.4214 5.17157 16.1716C4.42143 16.9217 4 17.9391 4 19V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <circle cx="12" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </div>
                  <h3>Profile</h3>
                  <p>View and update your profile information</p>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'bills' && (
          <div className="bills-section">
            <div className="section-header">
              <h2 className="section-title">Recent Bills</h2>
              <button className="btn btn-primary" onClick={() => navigate('/upload')}>
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <line x1="12" y1="5" x2="12" y2="19" stroke="currentColor" strokeWidth="2"/>
                  <line x1="5" y1="12" x2="19" y2="12" stroke="currentColor" strokeWidth="2"/>
                </svg>
                Upload New Bill
              </button>
            </div>
            
            <div className="table-container">
              <table className="table">
                <thead>
                  <tr>
                    <th>Description</th>
                    <th>Amount</th>
                    <th>Date</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {recentBills.map((bill) => (
                    <tr key={bill.id}>
                      <td>
                        <div className="bill-description">
                          <strong>{bill.description}</strong>
                        </div>
                      </td>
                      <td>
                        <span className="amount">{formatCurrency(bill.amount)}</span>
                      </td>
                      <td>
                        <span className="date">{new Date(bill.date).toLocaleDateString()}</span>
                      </td>
                      <td>
                        {getStatusBadge(bill.status)}
                      </td>
                      <td>
                        <button className="btn btn-outline btn-sm">
                          View Details
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'trips' && (
          <div className="trips-section">
            <div className="section-header">
              <h2 className="section-title">Your Trips</h2>
              <button className="btn btn-primary" onClick={() => navigate('/budget')}>
                <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <line x1="12" y1="5" x2="12" y2="19" stroke="currentColor" strokeWidth="2"/>
                  <line x1="5" y1="12" x2="19" y2="12" stroke="currentColor" strokeWidth="2"/>
                </svg>
                Plan New Trip
              </button>
            </div>
            
            <div className="trips-grid">
              {recentTrips.map((trip) => (
                <div key={trip.id} className="trip-card">
                  <div className="trip-header">
                    <h3 className="trip-destination">{trip.destination}</h3>
                    {getStatusBadge(trip.status)}
                  </div>
                  <p className="trip-purpose">{trip.purpose}</p>
                  <p className="trip-date">Start Date: {new Date(trip.startDate).toLocaleDateString()}</p>
                  <div className="trip-actions">
                    <button className="btn btn-outline btn-sm">View Details</button>
                    {trip.status === 'active' && (
                      <button className="btn btn-primary btn-sm">Manage Expenses</button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <style jsx>{`
        .employee-dashboard {
          min-height: 100vh;
          background: linear-gradient(135deg, var(--primary-50) 0%, var(--secondary-50) 100%);
          padding: var(--space-6);
        }

        .dashboard-loading {
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          min-height: 100vh;
          gap: var(--space-4);
        }

        .loading-spinner {
          width: 48px;
          height: 48px;
          border: 4px solid var(--secondary-200);
          border-top: 4px solid var(--primary-600);
          border-radius: 50%;
          animation: spin 1s linear infinite;
        }

        .dashboard-header {
          background: white;
          border-radius: var(--radius-2xl);
          padding: var(--space-8);
          margin-bottom: var(--space-8);
          box-shadow: var(--shadow-lg);
          border: 1px solid var(--secondary-100);
        }

        .header-content {
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .header-info {
          display: flex;
          align-items: center;
          gap: var(--space-4);
        }

        .user-avatar {
          width: 64px;
          height: 64px;
          border-radius: var(--radius-full);
          background: linear-gradient(135deg, var(--primary-600), var(--primary-700));
          display: flex;
          align-items: center;
          justify-content: center;
          color: white;
          font-size: var(--text-2xl);
          font-weight: var(--font-bold);
        }

        .user-name {
          font-size: var(--text-3xl);
          font-weight: var(--font-bold);
          color: var(--secondary-900);
          margin: 0 0 var(--space-1) 0;
        }

